import logo from './logo.svg';
import './App.css';
import React, { Component } from 'react'
import Navbar from './components/Navbar';


import NewsItem from './components/NewsItem';
// import News from './components/News';
import News from './components/News' ;
import {
  BrowserRouter as Router,
  Switch,
  Route,
  Link,
  Routes
} from "react-router-dom";
export default class App extends Component {

  render() {
    return (
      <div>
        <>
        <Router>
        <Navbar/>
       {/* <News pageSize={5} country="us" category ="general"/> */}
       <Switch>
        <Route exact path="/"><News pageSize={5} country="us" category ="general"/></Route>
        <Route exact path="/business"><News pageSize={5} country="us" category ="business"/></Route>
        <Route exact path="/entertainment"><News pageSize={5} country="us" category ="entertainment"/></Route>
        <Route exact path="/general"><News pageSize={5} country="us" category ="general"/></Route>
        <Route exact path="/health"><News pageSize={5} country="us" category ="health"/></Route>
        <Route exact path="/science"><News pageSize={5} country="us" category ="science"/></Route>
        <Route exact path="/sports"><News pageSize={5} country="us" category ="sports"/></Route>
        <Route exact path="/technology"><News pageSize={5} country="us" category ="technology"/></Route>
       </Switch>
       </Router>
        </>

      </div> 
    )
  }
}
